<script lang="ts">
  import { addRecurringPayment, cancelRecurringPayment, depositToVault, formatCharacterMoney, issueBankCard, loadPrepaidCard, makeCardPurchase, payCreditCard, repayLoan, setAutoDeposit, takeLoan, withdrawFromVault } from './lib/simulation';
  import type { Character, LoanType, PaymentSourceType } from './lib/types';
  let { character, onChange }: { character: Character; onChange: (next: Character) => void } = $props();
  let cardType = $state<'debit'|'credit'|'prepaid'>('debit'); let cardName = $state(''); let cardAccount = $state(''); let creditLimit = $state('5000');
  let loanType = $state<LoanType>('personal'); let loanName = $state(''); let loanAmount = $state('10000'); let loanRate = $state('8'); let loanTerm = $state('5'); let loanAccount = $state('');
  let recurringName = $state(''); let recurringAmount = $state('120'); let recurringCategory = $state<'subscription'|'bill'>('subscription'); let recurringSource = $state<PaymentSourceType>('cash'); let recurringSourceId = $state('');
  let depositMethod = $state<'fixed'|'percentage'>('percentage'); let depositValue = $state('10'); let depositAccount = $state('');
  let vaultAmount = $state('100'); let purchaseAmount = $state('100'); let purchaseDescription = $state('Purchase'); let selectedCard = $state(''); let cardPayAmount = $state('100'); let prepaidCardId = $state(''); let prepaidLoadAmount = $state('100'); let selectedLoan = $state(''); let loanPayAmount = $state('100');
  let notice = $state('');
  const accounts = $derived(character.bankAccounts ?? []); const cards = $derived(character.cards ?? []); const loans = $derived((character.loans ?? []).filter((loan)=>loan.active)); const recurring = $derived((character.recurringPayments ?? []).filter((item)=>item.active));
  const creditCards = $derived(cards.filter((card)=>card.type==='credit' && card.active)); const prepaidCards = $derived(cards.filter((card)=>card.type==='prepaid' && card.active)); const paymentCards = $derived(cards.filter((card)=>['credit','prepaid'].includes(card.type) && card.active));
  function n(value:string){const v=Number(value);return Number.isFinite(v)?Math.floor(v):0}
  function run(action:()=>Character,success:string){const next=action();if(next===character){notice='The action could not be completed. Check eligibility, balances, limits and selected accounts.';return;}onChange(next);notice=success;}
  function createCard(){run(()=>issueBankCard(character,cardType,cardName,cardAccount||undefined,n(creditLimit)),'Card issued.');cardName='';}
  function createLoan(){run(()=>takeLoan(character,loanType,loanName,n(loanAmount),Number(loanRate)/100,n(loanTerm),loanAccount||undefined),'Loan issued. Proceeds were added to cash.');loanName='';}
  function createRecurring(){run(()=>addRecurringPayment(character,recurringName,n(recurringAmount),recurringCategory,recurringSource,recurringSourceId||undefined),'Recurring payment saved.');recurringName='';}
  function createAutoDeposit(){run(()=>setAutoDeposit(character,depositAccount,depositMethod,n(depositValue)),'Automatic deposit configured.');}
  function depositVault(){run(()=>depositToVault(character,n(vaultAmount)),'Cash stored in your personal safe.');}
  function withdrawVault(){run(()=>withdrawFromVault(character,n(vaultAmount)),'Cash withdrawn from your personal safe.');}
  function buy(){run(()=>makeCardPurchase(character,selectedCard,n(purchaseAmount),purchaseDescription||'Card purchase'),'Purchase recorded.');}
  function loadPrepaid(){const card=prepaidCards.find((item)=>item.id===prepaidCardId);if(!card)return;run(()=>loadPrepaidCard(character,card.id,n(prepaidLoadAmount)),'Prepaid card loaded.');}\n  function payCard(){const card=creditCards.find((item)=>item.id===selectedCard);if(!card)return;run(()=>payCreditCard(character,card.id,n(cardPayAmount),card.linkedAccountId?'account':'cash',card.linkedAccountId),'Card payment completed.');}
  function payLoan(){const loan=loans.find((item)=>item.id===selectedLoan);if(!loan)return;run(()=>repayLoan(character,loan.id,n(loanPayAmount),loan.paymentAccountId?'account':'cash',loan.paymentAccountId),'Loan payment completed.');}
</script>
<section class="products-panel">
  <div class="products-title"><div><small>FINANCIAL TOOLS</small><h2>Credit, payments & savings</h2></div><span class="vault-total">Safe · {formatCharacterMoney(character,character.vaultBalance??0)}</span></div>
  <details><summary>Payment cards <span>{cards.length}/6</span></summary>
    {#each cards as card}<div class="product-row"><div><strong>{card.name}</strong><small>{card.type==='credit'?'Credit · '+formatCharacterMoney(character,card.balance)+' owed / '+formatCharacterMoney(character,card.creditLimit)+' limit':card.type==='prepaid'?'Prepaid · '+formatCharacterMoney(character,card.balance)+' available':'Debit · linked to '+(accounts.find((a)=>a.id===card.linkedAccountId)?.name??'unavailable account')}</small></div><b>{card.type==='credit'?formatCharacterMoney(character,Math.max(0,card.creditLimit-card.balance))+' available':card.type==='prepaid'?formatCharacterMoney(character,card.balance)+' stored':'Active'}</b></div>{/each}
    <div class="form-grid"><label>Card type<select bind:value={cardType}><option value="debit">Debit card</option><option value="credit">Credit card</option><option value="prepaid">Prepaid card</option></select></label><label>Card name<input bind:value={cardName} placeholder="Everyday card"/></label></div>
    {#if cardType==='debit'}<label>Bank account<select bind:value={cardAccount}><option value="">Select account</option>{#each accounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label>{:else if cardType==='credit'}<div class="form-grid"><label>Credit limit<input type="number" min="1" bind:value={creditLimit}/></label><label>Payment account (optional)<select bind:value={cardAccount}><option value="">Pay from cash</option>{#each accounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label></div><small class="hint">Simplified 18% annual interest. A 5% minimum payment is attempted each year.</small>{:else}<small class="hint">Prepaid cards have no credit line or interest. Load them from cash, then spend only the available balance.</small>{/if}
    <button class="primary" onclick={createCard} disabled={cards.length>=6 || (cardType==='debit' && accounts.length===0)}>Issue card</button>
    {#if cards.length>0}<div class="form-grid"><label>Record purchase with<select bind:value={selectedCard}><option value="">Choose card</option>{#each cards.filter((card)=>card.active) as card}<option value={card.id}>{card.name}</option>{/each}</select></label><label>Amount<input type="number" min="1" bind:value={purchaseAmount}/></label></div><label>Purchase description<input bind:value={purchaseDescription}/></label><button onclick={buy}>Record card purchase</button>{/if}
    {#if prepaidCards.length>0}<div class="form-grid"><label>Load prepaid card<select bind:value={prepaidCardId}><option value="">Choose prepaid card</option>{#each prepaidCards as card}<option value={card.id}>{card.name} · {formatCharacterMoney(character,card.balance)}</option>{/each}</select></label><label>Load amount<input type="number" min="1" bind:value={prepaidLoadAmount}/></label></div><button onclick={loadPrepaid}>Load prepaid card</button>{/if}
    {#if creditCards.length>0}<div class="form-grid"><label>Pay credit card<select bind:value={selectedCard}><option value="">Choose card</option>{#each creditCards as card}<option value={card.id}>{card.name} · {formatCharacterMoney(character,card.balance)} owed</option>{/each}</select></label><label>Payment amount<input type="number" min="1" bind:value={cardPayAmount}/></label></div><button onclick={payCard}>Pay card balance</button>{/if}
  </details>
  <details><summary>Loans <span>{loans.length}/5 active</span></summary>
    {#each loans as loan}<div class="product-row"><div><strong>{loan.name}</strong><small>{loan.type} · {(loan.annualInterestRate*100).toFixed(1)}% annual · {loan.termYears}-year term</small></div><b>{formatCharacterMoney(character,loan.balance)} owed</b></div>{/each}
    <div class="form-grid"><label>Loan type<select bind:value={loanType}><option value="personal">Personal</option><option value="mortgage">Mortgage</option><option value="business">Business</option></select></label><label>Name<input bind:value={loanName} placeholder="Personal loan"/></label><label>Principal<input type="number" min="1" bind:value={loanAmount}/></label><label>Annual interest %<input type="number" min="0" max="50" step="0.5" bind:value={loanRate}/></label><label>Term (years)<input type="number" min="1" max="30" bind:value={loanTerm}/></label><label>Repayment account<select bind:value={loanAccount}><option value="">Use cash</option>{#each accounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label></div>
    <button class="primary" onclick={createLoan} disabled={character.age<18 || loans.length>=5}>Take loan</button>
    {#if loans.length>0}<div class="form-grid"><label>Repay loan<select bind:value={selectedLoan}><option value="">Choose loan</option>{#each loans as loan}<option value={loan.id}>{loan.name} · {formatCharacterMoney(character,loan.balance)}</option>{/each}</select></label><label>Repayment amount<input type="number" min="1" bind:value={loanPayAmount}/></label></div><button onclick={payLoan}>Make extra repayment</button>{/if}
    <small class="hint">Annual interest accrues and a simplified principal installment is attempted automatically. Missed installments remain outstanding; interest is not erased.</small>
  </details>
  <details><summary>Subscriptions & recurring bills <span>{recurring.length}/12 active</span></summary>
    {#each recurring as item}<div class="product-row"><div><strong>{item.name}</strong><small>{item.category} · {item.sourceType} · {formatCharacterMoney(character,item.amount)} / year</small></div><button class="quiet" onclick={()=>run(()=>cancelRecurringPayment(character,item.id),'Recurring payment cancelled.')}>Cancel</button></div>{/each}
    <div class="form-grid"><label>Name<input bind:value={recurringName} placeholder="Music subscription"/></label><label>Annual amount<input type="number" min="1" bind:value={recurringAmount}/></label><label>Category<select bind:value={recurringCategory}><option value="subscription">Subscription</option><option value="bill">Recurring bill</option></select></label><label>Payment source<select bind:value={recurringSource}><option value="cash">Cash</option><option value="account">Bank account</option><option value="card">Credit card</option></select></label></div>
    {#if recurringSource==='account'}<label>Account<select bind:value={recurringSourceId}><option value="">Choose account</option>{#each accounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label>{:else if recurringSource==='card'}<label>Credit card<select bind:value={recurringSourceId}><option value="">Choose credit card</option>{#each paymentCards as card}<option value={card.id}>{card.name}</option>{/each}</select></label>{/if}
    <button class="primary" onclick={createRecurring} disabled={recurring.length>=12}>Add recurring payment</button><small class="hint">Charges run once per simulated year. Failed cash/account charges are logged as missed and do not create debt. Card charges use available credit.</small>
  </details>
  <details><summary>Automatic savings deposits</summary>
    <div class="form-grid"><label>Destination account<select bind:value={depositAccount}><option value="">Choose savings account</option>{#each accounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>Deposit method<select bind:value={depositMethod}><option value="percentage">Percentage of income</option><option value="fixed">Fixed amount / year</option></select></label><label>{depositMethod==='percentage'?'Percentage (1–90)':'Amount per year'}<input type="number" min="1" max={depositMethod==='percentage'?90:100000000} bind:value={depositValue}/></label></div>
    <button class="primary" onclick={createAutoDeposit} disabled={!depositAccount}>Save automatic deposit</button><small class="hint">Applied after annual income and household expenses, only when cash is sufficient.</small>
  </details>
  <details><summary>Personal safe / vault</summary>
    <div class="vault-balance"><small>STORED SECURELY</small><strong>{formatCharacterMoney(character,character.vaultBalance??0)}</strong></div>
    <label>Amount<input type="number" min="1" bind:value={vaultAmount}/></label><div class="action-row"><button onclick={depositVault}>Store cash</button><button onclick={withdrawVault}>Withdraw cash</button></div><small class="hint">The safe holds physical cash. It earns no interest and is included in net worth.</small>
  </details>
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
</section>
<style>
.products-panel{border:1px solid rgba(255,255,255,.09);border-radius:16px;padding:16px;margin:16px 0;background:rgba(255,255,255,.02)}.products-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:8px}.products-title small,.vault-total,.hint,.product-row small,.vault-balance small{color:var(--muted,#999);font-size:11px}.products-title h2{font-size:17px;margin:3px 0}.products-panel details{border-top:1px solid rgba(255,255,255,.08);padding:12px 0}.products-panel summary{cursor:pointer;font-size:13px;font-weight:700;display:flex;justify-content:space-between}.products-panel summary span{color:var(--muted,#999);font-weight:500}.product-row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.05)}.product-row strong,.product-row small{display:block}.product-row strong{font-size:12px}.product-row small{margin-top:3px}.product-row b{font-size:12px;white-space:nowrap}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}label{display:grid;gap:5px;margin:9px 0;color:var(--muted,#aaa);font-size:11px}input,select{width:100%;min-width:0;padding:10px;border:1px solid rgba(255,255,255,.13);border-radius:8px;background:#171a19;color:#f4f4f4;font:inherit;font-size:12px}.products-panel button{padding:9px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.06);color:inherit;font-size:11px;font-weight:650}.products-panel button.primary{background:var(--accent,#43d39e);color:#07150f;border:0}.products-panel button.quiet{padding:5px 8px}.action-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.vault-balance{padding:12px;border-radius:10px;background:rgba(255,255,255,.035)}.vault-balance strong{display:block;font-size:17px;margin-top:4px}.hint{display:block;line-height:1.5;margin:8px 0}.notice{font-size:12px;color:var(--accent,#43d39e)}@media(max-width:460px){.products-panel{padding:12px}.form-grid{grid-template-columns:1fr}.products-title{align-items:flex-start;flex-direction:column}}
</style>